sampler sampler_pw_noise_lq;
float2 uv0, uv1, uv2,uv4,rsk,dz1,Kugel1;;
static const float sw1 =  (0.6);
static const float sw2 =  (0.9);
shader_body {
uv0 = uv;
uv2 = float2(.2/rad+time/4,ang/3.14)*2;
float mod = length(sin(uv2*3.141/2+time*.1));
float2 noise = tex2D (sampler_noise_hq,uv2+mod).rg;
float mask = (noise.r <= sw2);
float2 rohr = sw1*rad * (noise-.5) /2*mask;
uv1 = float2(1-uv.x,uv.y);
ret =  GetPixel(uv)+GetPixel(uv1);
float3 back = .2*(.5+(uv.x-.5)*q1+(uv.y-.5)*q2);
uv+= rohr * sw1;
uv1 = float2(1-uv.x,uv.y);
ret += (GetBlur2(uv) + GetBlur2(uv1)) *min(.5+treb_att/4,2) *(1+sw1) * saturate(1-lum(ret)/2);
ret += !sw1*back;
ret = lerp(ret*(hue_shader*2-1),ret,lum(ret));;
//ret = GetPixel(uv);
//MilkDrop3 Color Mode:
ret /= float3(-1.1,-2.0,2.8);
//MilkDrop3 Shadows Mode:
ret += pow(tex2D(sampler_main,float2(uv.x,1-uv.y)).yyy+tex2D(sampler_main,1-uv).yyy,float3(1,2,3));
//MilkDrop3 Burn Mode:
ret = lerp(ret,2,GetPixel(uv).z*1.36);
}

